"""Writes docs/URDU_REVIEW.md: every Urdu / Roman Urdu text in the app, lesson by lesson, for checking.

Run:  python scripts/export_urdu.py
"""
import json
import pathlib
import re

ROOT = pathlib.Path(__file__).resolve().parent.parent
CONTENT = ROOT / "content"
out = ["# Urdu review sheet", "",
       "Every Urdu and Roman Urdu text in Angrezi. Fix mistakes directly in the JSON file named in each heading",
       "(or tell Claude which line to change). Generated by `python scripts/export_urdu.py`.", ""]


def cell(s):
    return str(s).replace("|", "\\|").replace("\n", " ")


def rows_from(obj, en=""):
    if isinstance(obj, dict) and "ur" in obj:
        return [(obj.get("en", en), obj["ur"], obj.get("roman", ""))]
    return []


def table(rows):
    if not rows:
        return []
    lines = ["| English | اردو | Roman Urdu |", "|---|---|---|"]
    lines += [f"| {cell(a)} | {cell(b)} | {cell(c)} |" for a, b, c in rows]
    return lines + [""]


def walk(ex):
    rows = []
    t = ex.get("type")
    if t == "tip":
        rows += rows_from(ex["text"], "(tip)")
        for e in ex.get("examples", []):
            rows += rows_from(e)
    for key in ("q", "meaning", "why", "hint", "scene"):
        if isinstance(ex.get(key), dict) and "ur" in ex[key]:
            label = {"q": ex.get("answer") if isinstance(ex.get("answer"), str) else "(question)",
                     "meaning": ex.get("say", ""), "why": "(why)", "hint": "(hint)", "scene": "(scene)"}[key]
            if key == "q" and isinstance(ex.get("options"), list) and isinstance(ex.get("answer"), int):
                o = ex["options"][ex["answer"]]
                label = o if isinstance(o, str) else "(question)"
            rows += rows_from(ex[key], label)
    for o in ex.get("options", []) if isinstance(ex.get("options"), list) else []:
        if isinstance(o, dict):
            rows += rows_from(o, "(" + (ex.get("q", {}).get("en", "") or "option") + ")")
    for p in ex.get("pairs", []):
        rows += rows_from(p)
    return rows


course = json.loads((CONTENT / "course.json").read_text(encoding="utf-8"))
for u in course["units"]:
    out.append(f"## {u['title']['en']} — {u['title']['ur']} ({u['title']['roman']})")
    out.append("")
    for l in u.get("lessons", []):
        path = CONTENT / "lessons" / f"{l['id']}.json"
        out.append(f"### {l['title']['en']} — `content/lessons/{l['id']}.json`")
        out.append("")
        rows = [(l["title"]["en"], l["title"]["ur"], l["title"]["roman"])]
        if path.exists():
            data = json.loads(path.read_text(encoding="utf-8"))
            rows += [(w["en"], w["ur"], w["roman"]) for w in data.get("words", [])]
            for ex in data.get("exercises", []):
                rows += walk(ex)
        seen, uniq = set(), []
        for r in rows:
            if r[1] not in seen:
                seen.add(r[1])
                uniq.append(r)
        out += table(uniq)

out.append("## Stories")
out.append("")
stories = json.loads((CONTENT / "stories" / "index.json").read_text(encoding="utf-8"))["stories"]
for st in stories:
    data = json.loads((CONTENT / "stories" / f"{st['id']}.json").read_text(encoding="utf-8"))
    out.append(f"### {st['title']['en']} — `content/stories/{st['id']}.json`")
    out.append("")
    rows = [(st["title"]["en"], st["title"]["ur"], st["title"]["roman"])]
    for item in data["items"]:
        rows += walk(item) if item.get("type") else rows_from(item)
    rows += [(k, g["ur"], g["roman"]) for k, g in data.get("glossary", {}).items()]
    out += table(rows)

out.append("## App buttons and messages — `strings.js`")
out.append("")
src = (ROOT / "strings.js").read_text(encoding="utf-8")
rows = []
for m in re.finditer(r'^\s*(\w+): \{ ur: (.+?), roman: (.+?) \},?$', src, re.M):
    rows.append((m.group(1), m.group(2).strip('"'), m.group(3).strip('"')))
out += table(rows)

(ROOT / "docs" / "URDU_REVIEW.md").write_text("\n".join(out), encoding="utf-8")
print("docs/URDU_REVIEW.md written")
